@namespace sv_fb4be9e1d1934b648a938549dc7cbb86.Components.Pages.Settings

<nav class="settings-sidebar">
    <h2 class="sidebar-title">Settings</h2>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")">
                <button @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };
}

.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    min-height: 100%;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.25rem;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-nav li button {
    display: block;
    width: 100%;
    padding: 0.75rem 1.5rem;
    border: none;
    background: transparent;
    text-align: left;
    font-size: 0.95rem;
    color: #555;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

.sidebar-nav li button:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-nav li.active button {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

